def test_reads_host_and_port(tmp_path: Path) -> None:
    cfg = tmp_path / "config.json"
    cfg.write_text(json.dumps({"host": "127.0.0.1", "port": 9999}))
    result = load_agentpulse_config(cfg)
    assert result == AgentPulseConfig(host="127.0.0.1", port=9999, fetch_limits=True)


def test_reads_fetch_limits_flag(tmp_path: Path) -> None:
    cfg = tmp_path / "config.json"
